<?php require_once 'includes.php';page_header('Share a car ride');$w=["trip_type='carpool'","status='open'","travel_date>=CURDATE()"];$p=[];$from=trim((string)($_GET['from']??''));$to=trim((string)($_GET['to']??''));$date=(string)($_GET['date']??'');if($from!==''){$w[]='from_city LIKE ?';$p[]="%$from%";}if($to!==''){$w[]='to_place LIKE ?';$p[]="%$to%";}if($date!==''&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)){$w[]='travel_date=?';$p[]=$date;}$s=db()->prepare('SELECT t.*,u.name host_name FROM trips t JOIN users u ON u.id=t.host_id WHERE '.implode(' AND ',$w).' ORDER BY travel_date');$s->execute($p);$trips=$s->fetchAll();?><section class="page-intro"><p class="eyebrow">ONE ROUTE, SHARED JOURNEY</p><h1>Find a seat. Share the ride.</h1><p>Find a driver travelling your way, or list empty passenger seats and coordinate a fair contribution.</p></section><div class="page-wrap"><div class="safety-note">Confirm the driver's identity, vehicle, route, seat belts, insurance and contribution before departure. This website does not independently verify drivers.</div><form class="filters-row panel" style="margin-top:20px"><label class="form-field">From<input name="from" value="<?=e($from)?>" placeholder="Hyderabad"></label><label class="form-field">To<input name="to" value="<?=e($to)?>" placeholder="Vijayawada"></label><label class="form-field">Date<input name="date" type="date" value="<?=e($date)?>"></label><button class="btn btn-primary">Find seats</button><a class="btn btn-light" href="rides.php">Clear</a></form><div class="section-heading"><div><h2>Available rides</h2><p><?=count($trips)?> rides found</p></div><a class="btn btn-primary" href="create-trip.php">+ Offer a seat</a></div><?php if(!$trips):?><div class="empty-state"><h3>No matching rides listed yet</h3><p>Try another route or offer a seat in your car.</p></div><?php else:?><div class="trip-list"><?php foreach($trips as $t):?><article class="trip-card"><div><span class="pill">Car seat sharing</span><h3 style="margin-top:12px"><?=e($t['title'])?></h3><p class="trip-meta"><?=e($t['from_city'])?> → <?=e($t['to_place'])?> · <?=e(date('d M Y',strtotime($t['travel_date'])))?> · <?= (int)$t['seats_available']?> seats · Driver <?=e($t['host_name'])?></p><p><strong>Vehicle:</strong> <?=e($t['vehicle']?:'To be confirmed')?> · <strong>Luggage:</strong> <?=e($t['luggage_notes']?:'Ask driver')?></p></div><div><div class="price">₹<?=number_format((float)$t['estimated_cost'])?> / person</div><a class="btn btn-primary" href="trip.php?id=<?=(int)$t['id']?>">Request seat</a></div></article><?php endforeach;?></div><?php endif;?></div><?php page_footer();?>